import Alpine from 'alpinejs';
import 'liquid-ajax-cart';
import log from '~/lib/log';

window.Alpine = Alpine;

// Create Alpine store for cart notifications
Alpine.store('cart', {
  lastAddedItem: null,
  showNotification: false,

  init() {
    // Alpine-native pattern: addEventListener within Alpine lifecycle
    document.addEventListener('liquid-ajax-cart:request-end', (event) => {
      this.handleCartRequestEnd(event);
    });
  },

  handleCartRequestEnd(event) {
    const { requestState } = event.detail;

    if (requestState.requestType === 'add') {
      if (requestState.responseData?.ok) {
        const addedItem = requestState.responseData.body?.items?.slice(-1)[0];
        this.handleCartAdd(addedItem);
      }
    }
  },

  handleCartAdd(addedItem) {
    this.lastAddedItem = addedItem;
    this.showNotification = true;
    log.info('✓ Item added to cart successfully!', addedItem?.product_title || 'Product');

    // Auto-hide notification after 3 seconds
    setTimeout(() => {
      this.showNotification = false;
    }, 3000);
  },
});

log.debug('Alpine.js Initializing…');
Alpine.start();
log.debug('Alpine.js Initialized!');
